fn all_digits(text: Str) -> Bool {
  if text.is_empty() {
    return false
  }
  for c in text.chars() {
    if not "0123456789".contains(c) {
      return false
    }
  }
  return true
}

pub fn inventory(orders: List[Str], stock: Map[Str, Int]) -> Result[List[Str], Str] {
  var left: Map[Str, Int] = stock
  var filled: List[Str] = []
  for order in orders {
    let fields = order.split(" ")
    let id = fields.get_or(0, "")
    if fields.len() != 2 or id == "" {
      return Err("bad order " + id)
    }
    var need: Map[Str, Int] = Map {}
    for part in fields.get_or(1, "").split(",") {
      let kv = part.split(":")
      if kv.len() != 2 {
        return Err("bad order " + id)
      }
      let iname = kv.get_or(0, "")
      let qty_text = kv.get_or(1, "")
      if iname == "" or not all_digits(qty_text) {
        return Err("bad order " + id)
      }
      let qty = qty_text.to_int().unwrap_or(0)
      if qty <= 0 or not stock.has(iname) {
        return Err("bad order " + id)
      }
      need = need.set(iname, need.get(iname).unwrap_or(0) + qty)
    }
    let have = left
    let wanted = need
    let can_fill = wanted.keys().all(fn(key) => have.get(key).unwrap_or(0) >= wanted.get(key).unwrap_or(0))
    if can_fill {
      for ky in wanted.keys() {
        left = left.set(ky, have.get(ky).unwrap_or(0) - wanted.get(ky).unwrap_or(0))
      }
      filled = filled.push(id)
    }
  }
  return Ok(filled)
}
